CREATE TRIGGER IF NOT EXISTS trg_ledger_no_update BEFORE UPDATE ON ledger_entries BEGIN SELECT RAISE(ABORT, 'append_only'); END;
CREATE TRIGGER IF NOT EXISTS trg_ledger_no_delete BEFORE DELETE ON ledger_entries BEGIN SELECT RAISE(ABORT, 'append_only'); END;
CREATE TRIGGER IF NOT EXISTS trg_audit_no_update BEFORE UPDATE ON audit_logs BEGIN SELECT RAISE(ABORT, 'append_only'); END;
CREATE TRIGGER IF NOT EXISTS trg_audit_no_delete BEFORE DELETE ON audit_logs BEGIN SELECT RAISE(ABORT, 'append_only'); END;
CREATE TRIGGER IF NOT EXISTS trg_events_no_update BEFORE UPDATE ON transaction_events BEGIN SELECT RAISE(ABORT, 'append_only'); END;
CREATE TRIGGER IF NOT EXISTS trg_events_no_delete BEFORE DELETE ON transaction_events BEGIN SELECT RAISE(ABORT, 'append_only'); END;
CREATE TRIGGER IF NOT EXISTS trg_recon_no_update BEFORE UPDATE ON bank_reconciliations BEGIN SELECT RAISE(ABORT, 'append_only'); END;
CREATE TRIGGER IF NOT EXISTS trg_recon_no_delete BEFORE DELETE ON bank_reconciliations BEGIN SELECT RAISE(ABORT, 'append_only'); END;
CREATE TRIGGER IF NOT EXISTS trg_income_insert_draft BEFORE INSERT ON income_transactions WHEN NEW.status <> 'draft' BEGIN SELECT RAISE(ABORT, 'initial_status_must_be_draft'); END;
CREATE TRIGGER IF NOT EXISTS trg_income_insert_year_open BEFORE INSERT ON income_transactions WHEN (SELECT status FROM fiscal_years WHERE id = NEW.fiscal_year_id) = 'closed' BEGIN SELECT RAISE(ABORT, 'fiscal_year_closed'); END;
CREATE TRIGGER IF NOT EXISTS trg_income_status_flow BEFORE UPDATE OF status ON income_transactions WHEN NEW.status <> OLD.status AND NOT ( (OLD.status = 'draft' AND NEW.status IN ('submitted', 'posted', 'rejected', 'cancelled')) OR (OLD.status = 'submitted' AND NEW.status IN ('posted', 'rejected')) OR (OLD.status = 'posted' AND NEW.status = 'reversed')) BEGIN SELECT RAISE(ABORT, 'invalid_status_transition'); END;
CREATE TRIGGER IF NOT EXISTS trg_income_post_year_open BEFORE UPDATE OF status ON income_transactions WHEN NEW.status <> OLD.status AND NEW.status IN ('posted', 'reversed') AND (SELECT status FROM fiscal_years WHERE id = NEW.fiscal_year_id) = 'closed' BEGIN SELECT RAISE(ABORT, 'fiscal_year_closed'); END;
CREATE TRIGGER IF NOT EXISTS trg_income_frozen BEFORE UPDATE ON income_transactions WHEN OLD.status IN ('posted', 'reversed', 'rejected', 'cancelled') AND ( NEW.fiscal_year_id IS NOT OLD.fiscal_year_id OR NEW.fund_source_id IS NOT OLD.fund_source_id OR NEW.receipt_number IS NOT OLD.receipt_number OR NEW.transaction_date IS NOT OLD.transaction_date OR NEW.payer_name IS NOT OLD.payer_name OR NEW.description IS NOT OLD.description OR NEW.amount_satang IS NOT OLD.amount_satang OR NEW.payment_method IS NOT OLD.payment_method OR NEW.created_by IS NOT OLD.created_by OR NEW.posted_by IS NOT OLD.posted_by OR NEW.posted_at IS NOT OLD.posted_at OR NEW.post_idempotency_key IS NOT OLD.post_idempotency_key) BEGIN SELECT RAISE(ABORT, 'immutable_after_post'); END;
CREATE TRIGGER IF NOT EXISTS trg_income_no_delete BEFORE DELETE ON income_transactions WHEN OLD.status <> 'draft' BEGIN SELECT RAISE(ABORT, 'delete_not_allowed'); END;
CREATE TRIGGER IF NOT EXISTS trg_expense_insert_draft BEFORE INSERT ON expense_transactions WHEN NEW.status <> 'draft' BEGIN SELECT RAISE(ABORT, 'initial_status_must_be_draft'); END;
CREATE TRIGGER IF NOT EXISTS trg_expense_insert_year_open BEFORE INSERT ON expense_transactions WHEN (SELECT status FROM fiscal_years WHERE id = NEW.fiscal_year_id) = 'closed' BEGIN SELECT RAISE(ABORT, 'fiscal_year_closed'); END;
CREATE TRIGGER IF NOT EXISTS trg_expense_project_fund_ins BEFORE INSERT ON expense_transactions WHEN NEW.project_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM projects p WHERE p.id = NEW.project_id AND p.fund_source_id = NEW.fund_source_id AND p.fiscal_year_id = NEW.fiscal_year_id) BEGIN SELECT RAISE(ABORT, 'project_fund_mismatch'); END;
CREATE TRIGGER IF NOT EXISTS trg_expense_project_fund_upd BEFORE UPDATE OF fund_source_id, project_id, fiscal_year_id ON expense_transactions WHEN NEW.project_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM projects p WHERE p.id = NEW.project_id AND p.fund_source_id = NEW.fund_source_id AND p.fiscal_year_id = NEW.fiscal_year_id) BEGIN SELECT RAISE(ABORT, 'project_fund_mismatch'); END;
CREATE TRIGGER IF NOT EXISTS trg_expense_status_flow BEFORE UPDATE OF status ON expense_transactions WHEN NEW.status <> OLD.status AND NOT ( (OLD.status = 'draft' AND NEW.status IN ('submitted', 'cancelled')) OR (OLD.status = 'submitted' AND NEW.status IN ('reviewed', 'rejected')) OR (OLD.status = 'reviewed' AND NEW.status IN ('approved', 'rejected')) OR (OLD.status = 'approved' AND NEW.status = 'paid') OR (OLD.status = 'paid' AND NEW.status = 'reversed')) BEGIN SELECT RAISE(ABORT, 'invalid_status_transition'); END;
CREATE TRIGGER IF NOT EXISTS trg_expense_post_year_open BEFORE UPDATE OF status ON expense_transactions WHEN NEW.status <> OLD.status AND NEW.status IN ('paid', 'reversed') AND (SELECT status FROM fiscal_years WHERE id = NEW.fiscal_year_id) = 'closed' BEGIN SELECT RAISE(ABORT, 'fiscal_year_closed'); END;
CREATE TRIGGER IF NOT EXISTS trg_expense_no_overspend BEFORE UPDATE OF status ON expense_transactions WHEN OLD.status = 'approved' AND NEW.status = 'paid' AND NEW.amount_satang > (SELECT COALESCE(SUM(amount_satang), 0) FROM ledger_entries WHERE fund_source_id = NEW.fund_source_id) BEGIN SELECT RAISE(ABORT, 'insufficient_funds'); END;
CREATE TRIGGER IF NOT EXISTS trg_expense_frozen BEFORE UPDATE ON expense_transactions WHEN OLD.status IN ('paid', 'reversed', 'rejected', 'cancelled') AND ( NEW.fiscal_year_id IS NOT OLD.fiscal_year_id OR NEW.fund_source_id IS NOT OLD.fund_source_id OR NEW.project_id IS NOT OLD.project_id OR NEW.voucher_number IS NOT OLD.voucher_number OR NEW.transaction_date IS NOT OLD.transaction_date OR NEW.payee_name IS NOT OLD.payee_name OR NEW.description IS NOT OLD.description OR NEW.amount_satang IS NOT OLD.amount_satang OR NEW.payment_method IS NOT OLD.payment_method OR NEW.created_by IS NOT OLD.created_by OR NEW.reviewed_by IS NOT OLD.reviewed_by OR NEW.approved_by IS NOT OLD.approved_by OR NEW.paid_by IS NOT OLD.paid_by OR NEW.paid_at IS NOT OLD.paid_at OR NEW.post_idempotency_key IS NOT OLD.post_idempotency_key) BEGIN SELECT RAISE(ABORT, 'immutable_after_post'); END;
CREATE TRIGGER IF NOT EXISTS trg_expense_no_delete BEFORE DELETE ON expense_transactions WHEN OLD.status <> 'draft' BEGIN SELECT RAISE(ABORT, 'delete_not_allowed'); END;
CREATE TRIGGER IF NOT EXISTS trg_ledger_year_open BEFORE INSERT ON ledger_entries WHEN (SELECT status FROM fiscal_years WHERE id = NEW.fiscal_year_id) = 'closed' BEGIN SELECT RAISE(ABORT, 'fiscal_year_closed'); END;
CREATE TRIGGER IF NOT EXISTS trg_ledger_source_income BEFORE INSERT ON ledger_entries WHEN NEW.kind = 'income' AND NOT EXISTS ( SELECT 1 FROM income_transactions t WHERE t.id = NEW.source_id AND t.status = 'posted' AND t.fund_source_id = NEW.fund_source_id AND t.fiscal_year_id = NEW.fiscal_year_id AND t.amount_satang = NEW.amount_satang) BEGIN SELECT RAISE(ABORT, 'ledger_source_mismatch'); END;
CREATE TRIGGER IF NOT EXISTS trg_ledger_source_expense BEFORE INSERT ON ledger_entries WHEN NEW.kind = 'expense' AND NOT EXISTS ( SELECT 1 FROM expense_transactions t WHERE t.id = NEW.source_id AND t.status = 'paid' AND t.fund_source_id = NEW.fund_source_id AND t.fiscal_year_id = NEW.fiscal_year_id AND -t.amount_satang = NEW.amount_satang) BEGIN SELECT RAISE(ABORT, 'ledger_source_mismatch'); END;
CREATE TRIGGER IF NOT EXISTS trg_ledger_reversal_match BEFORE INSERT ON ledger_entries WHEN NEW.kind = 'reversal' AND NOT EXISTS ( SELECT 1 FROM ledger_entries o WHERE o.id = NEW.reverses_entry_id AND o.kind IN ('income', 'expense') AND o.fund_source_id = NEW.fund_source_id AND o.source_type = NEW.source_type AND o.source_id = NEW.source_id AND o.amount_satang = -NEW.amount_satang) BEGIN SELECT RAISE(ABORT, 'ledger_source_mismatch'); END;
CREATE TRIGGER IF NOT EXISTS trg_ledger_reversal_state BEFORE INSERT ON ledger_entries WHEN NEW.kind = 'reversal' AND NOT ( (NEW.source_type = 'income' AND EXISTS (SELECT 1 FROM income_transactions t WHERE t.id = NEW.source_id AND t.status = 'reversed')) OR (NEW.source_type = 'expense' AND EXISTS (SELECT 1 FROM expense_transactions t WHERE t.id = NEW.source_id AND t.status = 'reversed'))) BEGIN SELECT RAISE(ABORT, 'ledger_source_mismatch'); END;
CREATE VIEW IF NOT EXISTS v_fund_summary AS SELECT f.id AS fund_source_id, f.source_name, f.color, COALESCE(SUM(CASE WHEN l.kind = 'opening' THEN l.amount_satang END), 0) AS opening_satang, COALESCE(SUM(CASE WHEN l.source_type = 'income' THEN l.amount_satang END), 0) AS income_net_satang, COALESCE(-SUM(CASE WHEN l.source_type = 'expense' THEN l.amount_satang END), 0) AS expense_net_satang, COALESCE(SUM(CASE WHEN l.kind = 'adjustment' THEN l.amount_satang END), 0) AS adjustment_satang, COALESCE(SUM(l.amount_satang), 0) AS balance_satang, (SELECT COALESCE(SUM(e.amount_satang), 0) FROM expense_transactions e WHERE e.fund_source_id = f.id AND e.status = 'approved') AS committed_satang FROM fund_sources f LEFT JOIN ledger_entries l ON l.fund_source_id = f.id GROUP BY f.id;
CREATE VIEW IF NOT EXISTS v_project_usage AS SELECT p.id AS project_id, p.fiscal_year_id, p.fund_source_id, p.project_code, p.project_name, p.budget_amount_satang, COALESCE((SELECT SUM(e.amount_satang) FROM expense_transactions e WHERE e.project_id = p.id AND e.status = 'paid'), 0) AS paid_satang, COALESCE((SELECT SUM(e.amount_satang) FROM expense_transactions e WHERE e.project_id = p.id AND e.status = 'approved'), 0) AS committed_satang FROM projects p;
CREATE VIEW IF NOT EXISTS v_integrity_issues_tx AS SELECT 'income_posted_without_ledger' AS issue, t.id AS entity_id FROM income_transactions t WHERE t.status IN ('posted', 'reversed') AND NOT EXISTS (SELECT 1 FROM ledger_entries l WHERE l.kind = 'income' AND l.source_id = t.id) UNION ALL SELECT 'expense_paid_without_ledger', t.id FROM expense_transactions t WHERE t.status IN ('paid', 'reversed') AND NOT EXISTS (SELECT 1 FROM ledger_entries l WHERE l.kind = 'expense' AND l.source_id = t.id) UNION ALL SELECT 'income_reversed_without_reversal_entry', t.id FROM income_transactions t WHERE t.status = 'reversed' AND NOT EXISTS (SELECT 1 FROM ledger_entries l WHERE l.kind = 'reversal' AND l.source_type = 'income' AND l.source_id = t.id);
CREATE VIEW IF NOT EXISTS v_integrity_issues_ledger AS SELECT 'expense_reversed_without_reversal_entry' AS issue, t.id AS entity_id FROM expense_transactions t WHERE t.status = 'reversed' AND NOT EXISTS (SELECT 1 FROM ledger_entries l WHERE l.kind = 'reversal' AND l.source_type = 'expense' AND l.source_id = t.id) UNION ALL SELECT 'ledger_posted_twice_for_same_source', l.source_id FROM ledger_entries l WHERE l.kind IN ('income', 'expense') GROUP BY l.kind, l.source_id HAVING COUNT(*) > 1 UNION ALL SELECT 'negative_fund_balance', s.fund_source_id FROM v_fund_summary s WHERE s.balance_satang < 0;
CREATE VIEW IF NOT EXISTS v_integrity_issues AS SELECT issue, entity_id FROM v_integrity_issues_tx UNION ALL SELECT issue, entity_id FROM v_integrity_issues_ledger;
